import { Lang } from '../App'
import { Pigment } from './pigments'

export type OpacityLevel = 'opaque' | 'semi-opaque' | 'semi-transparent' | 'transparent'

export interface PigmentLoreEntry {
  code: string
  chemicalFamily: Record<Lang, string>
  opacity: OpacityLevel
  lightfastness: string
  tintingStrength: Record<Lang, string>
  history: Record<Lang, string>
  leatherUsage: Record<Lang, string>
  whereToBuy: {
    leatherBrands: string[]
    pigmentSuppliers: string[]
    searchHint: Record<Lang, string>
  }
}

function defineLore(
  code: string,
  chemicalFamily: Record<Lang, string>,
  opacity: OpacityLevel,
  lightfastness: string,
  tintingStrength: Record<Lang, string>,
  history: Record<Lang, string>,
  leatherUsage: Record<Lang, string>,
  leatherBrands: string[],
  pigmentSuppliers: string[],
  searchHint: Record<Lang, string>
): PigmentLoreEntry {
  return {
    code,
    chemicalFamily,
    opacity,
    lightfastness,
    tintingStrength,
    history,
    leatherUsage,
    whereToBuy: { leatherBrands, pigmentSuppliers, searchHint },
  }
}

