/**
 * Возвращает подробный паспорт пигмента по его объекту из pigments.ts
 */
export function getPigmentLore(pigment: Pigment | undefined, lang: Lang): PigmentLoreEntry {
  if (!pigment) {
    return PIGMENT_LORE_DB.pw_6_anatase
  }
  return PIGMENT_LORE_DB[pigment.id] || PIGMENT_LORE_DB.pw_6_anatase
}

